def overlap_minutes(meetings: list[list[int]], k: int) -> int:
    events = {}
    for s, e in meetings:
        if s >= e:
            continue
        events[s] = events.get(s, 0) + 1
        events[e] = events.get(e, 0) - 1
    total = 0
    active = 0
    prev = None
    for t in sorted(events):
        if prev is not None and active >= k:
            total += t - prev
        active += events[t]
        prev = t
    return total
